import { useState } from 'react';
import { Languages } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import type { I18nText } from '@/lib/i18n-text';

interface I18nInputProps {
  value: I18nText;
  onChange: (val: I18nText) => void;
  placeholder?: string;
  label?: string;
  multiline?: boolean;
  rows?: number;
  disabled?: boolean;
  className?: string;
}

const LANGS: { code: 'en' | 'zh' | 'es' | 'ja'; label: string }[] = [
  { code: 'en', label: 'EN' },
  { code: 'zh', label: '中' },
  { code: 'es', label: 'ES' },
  { code: 'ja', label: '日' },
];

export default function I18nInput({
  value,
  onChange,
  placeholder,
  label,
  multiline = false,
  rows = 3,
  disabled = false,
  className = '',
}: I18nInputProps) {
  const [activeLang, setActiveLang] = useState<'en' | 'zh' | 'es' | 'ja'>('en');

  const handleChange = (code: 'en' | 'zh' | 'es' | 'ja', val: string) => {
    onChange({ ...value, [code]: val });
  };

  const currentValue = value[activeLang] ?? '';
  const hasEn = value.en && value.en.trim();

  return (
    <div className={`space-y-2 ${className}`}>
      <div className="flex items-center justify-between">
        {label && <label className="text-sm font-medium">{label}</label>}
        <div className="flex items-center ml-auto">
          {/* 语言切换 Tab */}
          <div className="flex items-center rounded-md border border-border bg-muted/30 p-0.5">
            {LANGS.map((lang) => {
              const hasContent = value[lang.code] && value[lang.code].trim();
              return (
                <button
                  key={lang.code}
                  type="button"
                  onClick={() => setActiveLang(lang.code)}
                  className={`relative px-2.5 py-1 text-xs font-medium rounded-sm transition-colors ${
                    activeLang === lang.code
                      ? 'bg-primary text-primary-foreground'
                      : 'text-muted-foreground hover:text-foreground'
                  }`}
                >
                  {lang.label}
                  {hasContent && activeLang !== lang.code && (
                    <span className="absolute top-0.5 right-0.5 w-1.5 h-1.5 rounded-full bg-success" />
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {multiline ? (
        <Textarea
          value={currentValue}
          onChange={(e) => handleChange(activeLang, e.target.value)}
          placeholder={placeholder || `Enter ${activeLang.toUpperCase()} text...`}
          rows={rows}
          disabled={disabled}
          className="resize-y"
        />
      ) : (
        <Input
          value={currentValue}
          onChange={(e) => handleChange(activeLang, e.target.value)}
          placeholder={placeholder || `Enter ${activeLang.toUpperCase()} text...`}
          disabled={disabled}
        />
      )}

      {/* 当前语言无内容时的提示 */}
      {activeLang !== 'en' && !currentValue.trim() && hasEn && (
        <p className="text-xs text-muted-foreground flex items-center gap-1">
          <Languages className="size-3" />
          No translation yet — use &quot;Translate All&quot; to batch translate
        </p>
      )}
    </div>
  );
}
